class Solution:
    def numberToWords(self, num: int) -> str:
        if num == 0:
            return "Zero"
        LESS_THAN_20 = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
        TENS = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"]
        THOUSANDS = ["", "Thousand", "Million", "Billion"]
        def convert(n):
            if n == 0: return ""
            if n < 20: return LESS_THAN_20[n]
            if n < 100: return TENS[n//10] + (" " + convert(n%10) if n%10 else "")
            return LESS_THAN_20[n//100] + " Hundred" + (" " + convert(n%100) if n%100 else "")
        result = []
        i = 0
        while num:
            chunk = num % 1000
            if chunk:
                chunk_words = convert(chunk)
                mag = THOUSANDS[i]
                result.insert(0, chunk_words + (" " + mag if mag else ""))
            num //= 1000
            i += 1
        return " ".join(result)

import sys
print(Solution().numberToWords(int(sys.stdin.read().strip())))
